$content = Get-Content "backend/src/main/kotlin/com/attendance/server/services/AttendanceService.kt" -Raw
$content = $content -replace "(?s)fun stopSession\(classId: String\) \{.*?// which is their current state\. Any zero-check is ABSENT, which is default\.`n        \}`n    \}", "fun stopSession(classId: String) {`n        transaction {`n            val cid = UUID.fromString(classId)`n            val session = AttendanceSessions.selectAll()`n                .where { (AttendanceSessions.classId eq cid) and (AttendanceSessions.sessionStatus eq `"ACTIVE`") }`n                .firstOrNull() ?: return@transaction`n`n            stopSession(session[AttendanceSessions.id])`n        }`n    }"
Set-Content "backend/src/main/kotlin/com/attendance/server/services/AttendanceService.kt" $content
